INSERT OR IGNORE INTO PostTag (postId, tagId) VALUES (1139, 144);
INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1132, 'Valkyrie &#8211; Kẻ Lựa Chọn Người Chết Trận', 'valkyrie', '<p>Valkyrie là một nhân vật nữ có nhiệm vụ lựa chọn từ những người chết trong các trận chiến. Họ là những nữ chiến thần cưỡi ngựa, mặt giáp, đội mũ sắt có sừng và mang theo khiên, giáo. Họ&nbsp;xuất hiện trong những tác phẩm văn học cổ như những cô gái xuất thân quý tộc hoặc một nữ anh hùng thiện nghệ. Họ đều có điểm chung là quý trọng những người anh hùng. Hoặc một ít tác phẩm còn miêu tả <strong>Valkyrie</strong> như một người phụ nữ trinh tiết xinh đẹp chết yểu. Ngày nay,&nbsp;họ&nbsp;thường được xuất hiện trong các tác phẩm truyện tranh, tiểu thuyết và trò chơi.</p>
<h3>Valkyrie &#8211; Kẻ lựa chọn những người chết trận</h3>
<p><figure id="attachment_1134" aria-describedby="caption-attachment-1134" style="width: 300px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1134" src="https://media.huynhhieutravel.com/Valkyrie.jpg" alt="Valkyrie" width="300" height="379"><figcaption id="caption-attachment-1134" class="wp-caption-text">Valkyrie</figcaption></figure></p>
<p>Tên gọi Valkyrie được ghép từ hai từ: <strong>valr</strong> (Tử sỉ chết trận) và <strong>kjósa</strong> (Sự chọn lựa).</p>
<h4>Hình dạng Valkyrie</h4>
<p>Hình dang của họ được miêu tả như những người trinh nữ xinh đẹp với mái tóc vàng và làn da trắng. Khi ra chiến trường họ mặt giáp đỏ, đội mũ vàng có sừng, cầm khiên và giáo, cưỡi trên một con ngựa thần có cánh. Mỗi khi cất cánh, con ngựa ấy tỏa ra những hạt nước như sương mai. Từ đó tạo ra những cầu vồng hay cực quang trên bầu trời khi nó đi ngang qua.</p>
<p><figure id="attachment_1136" aria-describedby="caption-attachment-1136" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1136" src="https://media.huynhhieutravel.com/Valkyrie-3.jpg" alt="Valkyrie" width="500" height="375"><figcaption id="caption-attachment-1136" class="wp-caption-text">Valkyrie</figcaption></figure></p>
<p>Thần thoại còn kể rằng khi xuống trần, các nàng hóa thành những con thiên nga. Và thường hay tắm bên các bờ suối vắng người. Hoặc bởi vì bộ giáp trên người các nàng làm bằng lông thiên nga nên người ta còn gọi Valkyrie là &#8220;Thiếu nữ thiên nga&#8221; (<i>Swan-Maiden).</i></p>
<h4>Nhiệm vụ của Valkyrie</h4>
<p>Từ cách ghép của cái tên Valkyrie chúng ta cũng có thể dễ dàng đoán được nhiệm vụ của các nàng. Họ len lỏi vào chiến trường, tìm ra những chiến binh đã chết trận dũng cảm nhất. Họ chọn ra phân nữa trong số đó để đem về điện thánh Valhalla. Ở Valhalla, những chiến binh đó sẽ không còn phục vụ các vị thần phụ thuộc khi còn sống nữa, mà họ trở thành&nbsp;<strong><i>Einherjar</i></strong>.</p>
<p><figure id="attachment_1135" aria-describedby="caption-attachment-1135" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1135" src="https://media.huynhhieutravel.com/Valkyrie2.jpg" alt="Valkyrie" width="500" height="375" srcset="https://media.huynhhieutravel.com/Valkyrie2.jpg 1024w, https://media.huynhhieutravel.com/Valkyrie2-768x576.jpg 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-1135" class="wp-caption-text">Valkyrie</figcaption></figure></p>
<p><strong>Einherjar&nbsp;</strong>hàng ngày luyện tập chiến đấu với nhau, tối đến họ sẽ tiệc tùng do các Valkyrie rót rượu.&nbsp;Vì thế, nhiệm vụ khác của các họ là&nbsp;phục vụ thức ăn chứa nhiều chất béo và rượu mật ong cho các chiến binh Einherjar.</p>
<h4>Nguồn gốc và sự phát triển Valkyrie</h4>
<p>Chúng ta có nhiều giả thuyết khác nhau về nguồn gốc thật sự của họ. Từ những giáo phái khác nhau ở Đức cho đến thần thoại Bắc Âu cũ.</p>
<p>Rudolf Simek (Một giáo sư nghiên cứu văn hóa) cho rằng&nbsp;họ có nguồn gốc ban đầu là những quái vật của cái chết. Nó đến từ những chiến binh bị tử trận. Sau này có sự thay đổi về nguồn gốc của Valkyrie khi có khái niệm &#8220;Valhalla&#8221;. Những quái vật của cái chết chuyển biến thành những chiến binh của thiên đường.&nbsp;Simek cho rằng nhờ sự thay đổi trong khái niệm mà họ trở nên nổi tiếng trong những bài thơ ca mô tả những anh hùng. Simek cho rằng Valkyrie đã được vẽ lại một cách bay bổng bằng những vầng thơ. Sự mơ mộng, một niềm tin vào cái tươi sáng giữa sự chết chóc, đau khổ ở chiến trường đã tạo nên một Valkyrie tươi sáng.</p>
<p>MacLeod và Mees (Những nhà nghiên cứu ngôn ngữ Anh) cho rằng vai trò của Valkyrie trở nên rối loạn hơn sau sự ra đời của Norse (Những người phụ nữ siêu nhiên chịu trách nhiệm về xác định số phận con người). Họ là những người có nhiệm vụ gần như Valkyrie.</p>
<p><span id="Freyja_and_Fólkvangr" class="mw-headline">Freyja cũng là một nhân vật liên quan đến Valkyrie. Phân nữa số người chết được họ dẫn về thế giới Valhalla, phân nữa còn lại sẽ được phân cho&nbsp;Freyja đưa về cánh đồng Fólkvangr.</span></p>
<h4>Ảnh hưởng đến văn hóa đại chúng hiện nay</h4>
<p>Valkyrie là chủ đề của nhiều bài thơ, tác phẩm nghệ thuật và âm nhạc. Trong văn thơ, Valkyrie xuất hiện trong &#8220;Die Walküren&#8221; của H. Heine (Xuất hiện trong Romanzero , 1847), &#8220;Die Walküren&#8221; (1864) của H.v.Linge, và &#8220;Sköldmon&#8221; (Xuất hiện trong Gömda Land , 1904).</p>
<p>Cái tên Valkyrie đã được Aston Martin sử dụng cho dòng xe siêu hạng cao cấp 2018 Aston Martin Valkyrie, đồng phát triển cùng với đội đua Red Bull Racing Formula 1. Theo Red Bull, cái tên đã được chọn để tiếp tục truyền thống của chiếc xe Aston Martin &#8220;V&#8221;. Và để phân biệt chiếc xe như một chiếc xe hiệu suất cao.<br />
<img loading="lazy" decoding="async" class="wp-image-1137" src="https://media.huynhhieutravel.com/Valkyrie-4.png" alt="Valkyrie" width="500" height="395" srcset="https://media.huynhhieutravel.com/Valkyrie-4.png 813w, https://media.huynhhieutravel.com/Valkyrie-4-768x606.png 768w" sizes="(max-width: 500px) 100vw, 500px" /><br />
Nhân vật Valkyrie trong một trò chơi.</p>
<p>Một số game hiện nay cũng xuất hiện những nhân vật mang tên Valkyrie. Nó xuất hiện với hình tượng vẽ ra gần như miêu tả trong văn học cổ của thần thoại Bắc Âu.</p>
<p><strong><em>Nguồn tham khảo: Wiki, Google, Norse mythology.</em></strong></p>
', 'Valkyrie là một nhân vật nữ có nhiệm vụ lựa chọn từ những người chết trong các trận chiến. Họ là những nữ chiến thần cưỡi ngựa, mặt giáp, đội mũ sắt có sừng và mang theo khiên, giáo. Họ xuất hiện trong những tác phẩm văn học cổ như những cô gái xuất thân quý [&hellip;]', 1135, 'post', '2018-07-16 09:42:11', '2023-04-23 12:33:52');
INSERT OR IGNORE INTO PostCategory (postId, categoryId) VALUES (1132, 431);
