INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1052, 'Bikini &#8211; Lịch Sử Bộ Đồ Tắm Quyến Rũ', 'bikini', '<p>Bikini &#8211; bộ đồ tắm huyền bí đầy ma mị đã quyến rũ biết bao thế hệ đàn ông khi người phụ nữ mặc vào. Nó là chất liệu không thể thiếu cho chị em phụ nữ khi đi biển. Nó tôn vinh vóc dáng của người phụ nữ lên cao. Hay sự tiện dụng của nó cũng khiến ta thích thú. Cùng Huynh Hieu Travel tìm hiểu về lịch sử của nó nhé!</p>
<h2>Bikini</h2>
<p>Bộ đồ bơi hai mảnh được ra mắt vào ngày 5 tháng 7 năm 1946.</p>
<p><figure id="attachment_1053" aria-describedby="caption-attachment-1053" style="width: 1280px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1053 size-full" src="https://media.huynhhieutravel.com/bikini.jpg" alt="bikini" width="1280" height="720" srcset="https://media.huynhhieutravel.com/bikini.jpg 1280w, https://media.huynhhieutravel.com/bikini-768x432.jpg 768w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption id="caption-attachment-1053" class="wp-caption-text">Bikini</figcaption></figure></p>
<p>Nguyên mẫu của bộ bikini hai mảnh có thể được bắt nguồn từ triều đại của hoàng để La Mã Diocletian (244-311).</p>
<h4>Từ sự khiếm nhã nơi công cộng&#8230;</h4>
<p>Bộ bikini hai mảnh đầu tiên xuất hiện vào những năm 1930. Và nó được cho là quá khiếm nhã để mặc ở nơi công cộng. Tuy nhiên nó đã trở nên phổ biến hơn ở Mỹ trong Chiến tranh thế giới thứ hai. Do quy định của Ủy ban sản xuất chiến tranh Hoa Kỳ L-85 yêu cầu giảm 10% lượng vật liệu được sử dụng trong đồ tắm biển của phụ nữ.</p>
<p>Mẫu áo tắm hiện đại lần đầu tiên được giới thiệu với báo chí ngày 5 tháng 7 năm 1946. Nó được giới thiệu bởi một kỹ sư người Pháp là Louis Réard và nhà thiết kế thời trang Jacques Heim.</p>
<h4>Cắt nhỏ áo tắm nhỏ nhất thế giới để được áo tắm nhỏ hơn&#8230;</h4>
<p>Bộ đồ &#8216;Atome&#8217; của Heim được quảng cáo là &#8216;áo tắm nhỏ nhất trên thế giới&#8217;, mặc dù nó vẫn che phủ rốn.&nbsp;Réard đã cắt nhỏ Atome &#8211; cắt nhỏ áo tắm nhỏ nhất thế giới nhỏ hơn nữa. Trùng hợp là ngay sau khi ra mắt bộ &#8220;bikini&#8221; đó, cuộc thử nghiệm hạt nhân đầu tiên được diễn ra trên quần đảo san hô có tên Bikini. Thế là bộ đồ được đặt tên Bikini để diễn tả một sự chấn động mà nó gây ra khi cho ra mắt.</p>
<p><figure id="attachment_1054" aria-describedby="caption-attachment-1054" style="width: 1280px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1054" src="https://media.huynhhieutravel.com/bikini2.jpg" alt="Bikini" width="1280" height="720" srcset="https://media.huynhhieutravel.com/bikini2.jpg 1280w, https://media.huynhhieutravel.com/bikini2-768x432.jpg 768w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption id="caption-attachment-1054" class="wp-caption-text">Bikini</figcaption></figure></p>
<p>Không thể tìm thấy một người mẫu nào sẵn sàng mặc trang phục táo bạo. Réard thuê Micheline Bernardini, một vũ công khỏa thân đến từ một sòng bài ở Paris. Người sau này đã nhận được hơn 50.000 lá thư của người hâm mộ sau khi xuất hiện.&nbsp;Mặc dù vậy, bộ bikini ban đầu không bán được tốt và Réard trở lại sản xuất đồ lót.</p>
<h4>Bị từ chối ở cuộc thi hoa hậu thế giới&#8230;</h4>
<p>Vào năm 1951, bikini trở thành một trong những phần thi của hoa hậu thế giới. Nhưng sau buổi thử nghiệm đầu tiên, nó bị phản đối bởi nhiều nhà hoạt động và cả&nbsp;Giáo hoàng Pius XII. Nên sau 1 năm thử nghiệm, nó bị thay đổi bởi phần thi áo choàng buổi tối.</p>
<p>Với việc bãi bỏ Bộ luật Hays Code ở Mỹ, bikini bắt đầu xuất hiện trong các bộ phim trong thập niên 1960. Mặc dù vẫn bị cấm ở nhiều nơi công cộng trong nước.</p>
<p><em>Bộ luật Hays Code là bộ luật cấm đoán, hạn chế những hình ảnh được cho là không hợp lý nơi công cộng và màn ảnh. Sau này vì ảnh hưởng quyền tự do và cũng như du khách đến Mỹ. Nó đã bị bãi bỏ.</em></p>
<p><figure id="attachment_1055" aria-describedby="caption-attachment-1055" style="width: 1200px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1055" src="https://media.huynhhieutravel.com/bikini3.jpg" alt="Bikini" width="1200" height="800" srcset="https://media.huynhhieutravel.com/bikini3.jpg 1200w, https://media.huynhhieutravel.com/bikini3-768x512.jpg 768w" sizes="(max-width: 1200px) 100vw, 1200px" /><figcaption id="caption-attachment-1055" class="wp-caption-text">Bikini</figcaption></figure></p>
<h4>Đến sự thịnh hành nhờ truyền thông</h4>
<p>Tuy vậy, nghệ thuật đã đem bikini trở lại. Năm 1957 bộ bikini của Brigitte Bardot trong bộ phim <strong><i>And God Created Woman</i></strong> đã mở ra một thị trường mới cho bikini tại Hoa Kỳ. Trong năm 1960, bài hát nhạc pop &#8220;Itsy Bitsy Teenie Weenie Yellow Polka Dot Bikini&#8221; của Brian Hyland đã gây nên một trào lưu mua đồ bơi bikini. Bikini đã trở thành một cảnh tượng phổ biến trên bãi biển.</p>
', 'Bikini &#8211; bộ đồ tắm huyền bí đầy ma mị đã quyến rũ biết bao thế hệ đàn ông khi người phụ nữ mặc vào. Nó là chất liệu không thể thiếu cho chị em phụ nữ khi đi biển. Nó tôn vinh vóc dáng của người phụ nữ lên cao. Hay sự tiện dụng [&hellip;]', 1053, 'post', '2018-07-10 03:37:43', '2023-04-23 12:33:53');
